package view;
import bus.staff.StaffBUS;import java.awt.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import model.auth.AuthenticatedSession;import model.staff.StaffModels.Staff;import view.component.UIStyle;
final class StaffPanel extends JPanel{private final AuthenticatedSession session;private final StaffBUS bus;private final boolean doctors;private final JTextField search=new JTextField();private final DefaultTableModel model=new DefaultTableModel(new Object[]{"Mã NV","Họ tên","Bộ phận","Chức danh","Chuyên khoa","Điện thoại","Trạng thái","__row"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);private final JButton edit=new JButton("Chỉnh sửa");StaffPanel(AuthenticatedSession s,StaffBUS b,boolean d){session=s;bus=b;doctors=d;setLayout(new BorderLayout(0,16));setBackground(MainFrame.PAGE);setBorder(BorderFactory.createEmptyBorder(25,28,30,28));add(header(),BorderLayout.NORTH);add(body(),BorderLayout.CENTER);load();}private JPanel header(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);JPanel l=new JPanel();l.setOpaque(false);l.setLayout(new BoxLayout(l,BoxLayout.Y_AXIS));JLabel t=new JLabel(doctors?"Quản lý bác sĩ":"Quản lý nhân viên");t.setFont(new Font("Segoe UI",Font.BOLD,25));t.setForeground(MainFrame.TEXT);JLabel d=new JLabel(doctors?"Theo dõi hồ sơ chuyên môn, chứng chỉ và chuyên khoa.":"Quản lý hồ sơ nhân sự và trạng thái làm việc.");d.setForeground(MainFrame.MUTED);l.add(t);l.add(d);JButton add=new JButton("+ Thêm nhân viên");UIStyle.primaryButton(add);add.addActionListener(e->open(null));p.add(l,BorderLayout.WEST);p.add(add,BorderLayout.EAST);return p;}private JPanel body(){JPanel p=new JPanel(new BorderLayout(0,12));p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(MainFrame.BORDER),BorderFactory.createEmptyBorder(16,16,16,16)));JPanel bar=new JPanel(new BorderLayout(8,0));bar.setOpaque(false);search.setPreferredSize(new Dimension(380,36));search.putClientProperty("JTextField.placeholderText","Tìm mã, họ tên, số điện thoại...");bar.add(search,BorderLayout.CENTER);UIStyle.secondaryButton(edit);edit.setEnabled(false);edit.addActionListener(e->{Staff x=selected();if(x!=null)open(x);});bar.add(edit,BorderLayout.SOUTH);table.setRowHeight(40);UIStyle.table(table);table.setAutoCreateRowSorter(true);table.getSelectionModel().addListSelectionListener(e->edit.setEnabled(table.getSelectedRow()>=0));p.add(bar,BorderLayout.NORTH);p.add(new JScrollPane(table),BorderLayout.CENTER);search.addActionListener(e->load());return p;}private Staff selected(){int r=table.getSelectedRow();return r<0?null:(Staff)table.getValueAt(table.convertRowIndexToModel(r),7);}private void open(Staff x){new StaffDialog(SwingUtilities.getWindowAncestor(this),session,bus,x,doctors).setVisible(true);load();}private void load(){new SwingWorker<java.util.List<Staff>,Void>(){protected java.util.List<Staff> doInBackground(){return bus.find(session,search.getText(),doctors);}protected void done(){try{model.setRowCount(0);for(Staff x:get())model.addRow(new Object[]{x.id(),x.name(),x.departmentName(),x.titleName(),x.specialty(),x.phone(),x.status(),x});table.getColumnModel().getColumn(7).setMinWidth(0);table.getColumnModel().getColumn(7).setMaxWidth(0);table.getColumnModel().getColumn(7).setWidth(0);}catch(Exception e){UIStyle.showError(StaffPanel.this,e.getCause()==null?e.getMessage():e.getCause().getMessage());}}}.execute();}}
